"""Tests for the generated lab-results-intake pipeline (generated by Pipeline Factory)."""

import csv
import importlib.util
from pathlib import Path

import pytest

SPEC_DIR = Path(__file__).parent
MODULE_PATH = SPEC_DIR / "pipeline_lab-results-intake.py"

EXPECTED_GOVERNED = 2
EXPECTED_QUARANTINED = 1
RAW_PII_VALUES = ['Alice Example', 'Bob Sample', 'Carol Demo']


def _load():
    spec = importlib.util.spec_from_file_location("pipeline_lab-results-intake", MODULE_PATH)
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod


@pytest.fixture()
def sample_csv(tmp_path):
    path = tmp_path / "input.csv"
    rows = [
        {'patient_id': 'Alice Example', 'test_name': 'E11', 'result_value': '70.0', 'result_date': '2026-11-01'},
        {'patient_id': 'Bob Sample', 'test_name': 'I10', 'result_value': '10001', 'result_date': '2026-11-01'},
        {'patient_id': 'Carol Demo', 'test_name': 'J45', 'result_value': '72.0', 'result_date': '2026-11-01'},
    ]
    with open(path, "w", newline="") as fh:
        writer = csv.DictWriter(fh, fieldnames=list(rows[0]))
        writer.writeheader()
        writer.writerows(rows)
    return path


def test_governed_output_has_no_raw_pii(sample_csv, tmp_path):
    mod = _load()
    mod.run(sample_csv, tmp_path / "gov.csv", tmp_path / "quar.csv")
    text = (tmp_path / "gov.csv").read_text()
    for raw in RAW_PII_VALUES:
        assert raw not in text


def test_governed_and_quarantine_counts(sample_csv, tmp_path):
    mod = _load()
    gov, quar = mod.run(sample_csv, tmp_path / "gov.csv", tmp_path / "quar.csv")
    assert gov == EXPECTED_GOVERNED
    assert quar == EXPECTED_QUARANTINED


def test_counts_add_up(sample_csv, tmp_path):
    mod = _load()
    gov, quar = mod.run(sample_csv, tmp_path / "gov.csv", tmp_path / "quar.csv")
    assert gov + quar == 3


def test_quarantine_reason_recorded(sample_csv, tmp_path):
    mod = _load()
    mod.run(sample_csv, tmp_path / "gov.csv", tmp_path / "quar.csv")
    qtext = (tmp_path / "quar.csv").read_text()
    if EXPECTED_QUARANTINED:
        assert "out of range" in qtext


def test_audit_record_written(sample_csv, tmp_path):
    mod = _load()
    audit = tmp_path / "audit.jsonl"
    mod.run(sample_csv, tmp_path / "gov.csv", tmp_path / "quar.csv",
            audit_path=audit)
    assert audit.exists()
    assert f'"governed": {EXPECTED_GOVERNED}' in audit.read_text()
